import{_ as i,o as t,c as o,ag as e}from"./chunks/framework.S-Qvb3wi.js";const p=JSON.parse('{"title":"Understanding Authorisations","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/usage/oauth2-authorisations.md","filePath":"user-guide/usage/oauth2-authorisations.md"}'),s={name:"user-guide/usage/oauth2-authorisations.md"};function n(r,a,u,l,c,h){return t(),o("div",null,a[0]||(a[0]=[e('<h1 id="understanding-authorisations" tabindex="-1">Understanding Authorisations <a class="header-anchor" href="#understanding-authorisations" aria-label="Permalink to &quot;Understanding Authorisations&quot;">​</a></h1><p>When you log in to an application using Citizen iD, you grant that application an &quot;authorisation&quot; to access parts of your account data. These authorisations are based on <strong>Scopes</strong>.</p><h2 id="what-is-a-scope" tabindex="-1">What is a Scope? <a class="header-anchor" href="#what-is-a-scope" aria-label="Permalink to &quot;What is a Scope?&quot;">​</a></h2><p>A scope is a specific permission category. Common scopes include:</p><ul><li><strong>Profile</strong>: Access to your display name and avatar.</li><li><strong>RSI Profile</strong>: Access to your verified RSI handle and selected profile data.</li><li><strong>RSI Organizations</strong>: Access to your public RSI organization memberships.</li><li><strong>Email</strong>: Access to your email address.</li><li><strong>Offline Access</strong>: The ability to access your data even when you are not actively using the application (background sync),</li><li><em>and more</em>.</li></ul><h2 id="viewing-your-authorisations" tabindex="-1">Viewing Your Authorisations <a class="header-anchor" href="#viewing-your-authorisations" aria-label="Permalink to &quot;Viewing Your Authorisations&quot;">​</a></h2><p>You can view all applications you have authorised in your <a href="https://citizenid.space/account/apps" target="_blank" rel="noreferrer">Citizen iD Authorized Apps</a>. This list shows:</p><ul><li>The name of the application.</li><li>The date you first authorised it.</li><li>The specific permissions (scopes) it has access to.</li></ul><hr><p><em>Last updated: February 2026</em></p>',10)]))}const g=i(s,[["render",n]]);export{p as __pageData,g as default};
